import{_ as e,c as s,o as i,aj as l}from"./chunks/framework.VtnL2jmu.js";const k=JSON.parse('{"title":"ZestSend部署","description":"","frontmatter":{},"headers":[],"relativePath":"tool/ZestSend.md","filePath":"tool/ZestSend.md"}'),n={name:"tool/ZestSend.md"};function r(t,a,d,o,h,c){return i(),s("div",null,[...a[0]||(a[0]=[l(`<h1 id="zestsend部署" tabindex="-1">ZestSend部署 <a class="header-anchor" href="#zestsend部署" aria-label="Permalink to “ZestSend部署”">​</a></h1><h2 id="一、项目简介" tabindex="-1">一、项目简介 <a class="header-anchor" href="#一、项目简介" aria-label="Permalink to “一、项目简介”">​</a></h2><p>ZestSend 是一个基于 WebRTC 的开源工具，核心功能是<strong>发一个链接，对方点开就能进行点对点语音通话或文件传输</strong>。它使用端到端加密，数据不经过中心服务器，隐私性较好。</p><p>项目地址：<a href="https://github.com/RavelloH/ZestSend" target="_blank" rel="noreferrer">https://github.com/RavelloH/ZestSend</a></p><p><img src="http://cdn.qiniu.liyansheng.top/img/image-20260924003713588.png" alt="image-20260924003713588"></p><p><img src="http://cdn.qiniu.liyansheng.top/img/image-20260924003848630.png" alt="image-20260924003848630"></p><p><img src="http://cdn.qiniu.liyansheng.top/img/image-20260924003921507.png" alt="image-20260924003921507"></p><hr><h2 id="二、部署方案选择" tabindex="-1">二、部署方案选择 <a class="header-anchor" href="#二、部署方案选择" aria-label="Permalink to “二、部署方案选择”">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>优点</th><th>缺点</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>Cloudflare Worker</strong></td><td>零运维、免费额度充足、部署简单</td><td>国内访问速度不稳定、<code>workers.dev</code> 被屏蔽</td><td>个人使用、能接受偶尔慢</td></tr><tr><td><strong>自建服务器</strong></td><td>国内访问稳定、完全可控</td><td>需要自己维护、<code>workerd</code> 对系统版本有要求</td><td>面向国内用户、追求稳定</td></tr></tbody></table><p><strong>最终选择</strong>：Cloudflare Worker + 自定义域名 <code>send.example.com</code></p><hr><h2 id="三、部署过程回顾" tabindex="-1">三、部署过程回顾 <a class="header-anchor" href="#三、部署过程回顾" aria-label="Permalink to “三、部署过程回顾”">​</a></h2><h3 id="_1-在-cloudflare-部署-worker" tabindex="-1">1. 在 Cloudflare 部署 Worker <a class="header-anchor" href="#_1-在-cloudflare-部署-worker" aria-label="Permalink to “1. 在 Cloudflare 部署 Worker”">​</a></h3><ul><li>Fork ZestSend 仓库到自己的 GitHub</li><li>在 Cloudflare Dashboard 创建 Worker，导入仓库</li><li>配置构建命令和部署命令</li><li>部署成功后获得 <code>zestsend.&lt;你的子域&gt;.workers.dev</code> 地址</li></ul><h3 id="_2-域名-ns-迁移到-cloudflare" tabindex="-1">2. 域名 NS 迁移到 Cloudflare <a class="header-anchor" href="#_2-域名-ns-迁移到-cloudflare" aria-label="Permalink to “2. 域名 NS 迁移到 Cloudflare”">​</a></h3><ul><li>在原 DNS 服务商处，把 <code>example.com</code> 的 NS 服务器改为 Cloudflare 分配的两台 NS</li><li><strong>注意</strong>：迁移前需在 Cloudflare 补全所有原有 DNS 记录，否则相关服务会失联</li></ul><h3 id="_3-绑定自定义域名" tabindex="-1">3. 绑定自定义域名 <a class="header-anchor" href="#_3-绑定自定义域名" aria-label="Permalink to “3. 绑定自定义域名”">​</a></h3><ul><li>在 Worker 设置里添加自定义域 <code>send.example.com</code></li><li>Cloudflare 自动创建 CNAME 记录并签发 SSL 证书</li></ul><hr><h2 id="四、踩坑记录" tabindex="-1">四、踩坑记录 <a class="header-anchor" href="#四、踩坑记录" aria-label="Permalink to “四、踩坑记录”">​</a></h2><h3 id="坑-1-nginx-泛域名规则导致-500" tabindex="-1">坑 1：Nginx 泛域名规则导致 500 <a class="header-anchor" href="#坑-1-nginx-泛域名规则导致-500" aria-label="Permalink to “坑 1：Nginx 泛域名规则导致 500”">​</a></h3><ul><li><strong>现象</strong>：访问 <code>send.example.com</code> 返回 <code>500 Internal Server Error</code>，错误页显示 <code>nginx/1.20.1</code></li><li><strong>原因</strong>：域名解析回源到了自己的服务器，被 Nginx 泛域名规则 <code>~^(?&lt;subdomain&gt;.+)\\.example\\.com$</code> 接住，去 <code>/www/send</code> 找文件失败</li><li><strong>解决</strong>：确保 Cloudflare DNS 里 <code>send</code> 记录指向 Worker，而非服务器 IP</li></ul><h3 id="坑-2-flclash-代理导致-dns-解析错误" tabindex="-1">坑 2：FlClash 代理导致 DNS 解析错误 <a class="header-anchor" href="#坑-2-flclash-代理导致-dns-解析错误" aria-label="Permalink to “坑 2：FlClash 代理导致 DNS 解析错误”">​</a></h3><ul><li><strong>现象</strong>：代理开启时，访问返回 500，FlClash 显示 DIRECT 但依然无效</li><li><strong>原因</strong>：FlClash 的 FakeIP 模式 + DNS 接管，导致本机解析 <code>send.example.com</code> 时得到错误 IP，请求被导向服务器而非 Cloudflare</li><li><strong>解决</strong>： <ul><li>在 FlClash 的“附加规则”里添加 <code>DOMAIN-SUFFIX,send.example.com,DIRECT</code></li><li>打开“覆写 DNS”，默认域名服务器填 <code>1.1.1.1</code>，Fallback 填 <code>8.8.8.8</code></li><li>把 DNS 模式从 <code>FakeIP</code> 改为 <code>redir-host</code>（或把域名加入 FakeIP 过滤）</li><li>保存后重启 FlClash 内核</li></ul></li></ul><h3 id="坑-3-本机-dns-缓存" tabindex="-1">坑 3：本机 DNS 缓存 <a class="header-anchor" href="#坑-3-本机-dns-缓存" aria-label="Permalink to “坑 3：本机 DNS 缓存”">​</a></h3><ul><li><strong>现象</strong>：公共 DNS 解析正确，但本机访问仍 500</li><li><strong>解决</strong>：<code>ipconfig /flushdns</code>，或手动改本机 DNS 为 <code>1.1.1.1</code></li></ul><hr><h2 id="五、关键命令" tabindex="-1">五、关键命令 <a class="header-anchor" href="#五、关键命令" aria-label="Permalink to “五、关键命令”">​</a></h2><div class="language-powershell"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 清除本机 DNS 缓存</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ipconfig </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flushdns</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 用公共 DNS 查询解析结果</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">nslookup </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">send.example.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.1</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 强制指定 IP 请求，绕过本机 DNS</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">curl.exe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">I </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">resolve </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">send.example.com</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">443</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Cloudflare_IP</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">send.example.com</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 直接请求，看响应头</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">curl.exe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">I https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">send.example.com</span></span></code></pre></div><p><strong>成功标志</strong>：返回 <code>server: cloudflare</code> 和 <code>307</code> 重定向，而不是 <code>nginx/1.20.1</code> 的 500。</p><hr><h2 id="六、后续可优化项" tabindex="-1">六、后续可优化项 <a class="header-anchor" href="#六、后续可优化项" aria-label="Permalink to “六、后续可优化项”">​</a></h2><h3 id="_1-配置-turn-中继-可选" tabindex="-1">1. 配置 TURN 中继（可选） <a class="header-anchor" href="#_1-配置-turn-中继-可选" aria-label="Permalink to “1. 配置 TURN 中继（可选）”">​</a></h3><ul><li>位置：Cloudflare Dashboard → Realtime → TURN</li><li>作用：在双方都处于严格 NAT 环境时，通过中继保证通话连通</li><li>配置：生成凭证后，在 Worker 的 Settings → Variables and Secrets 添加 <code>TURN_ID</code> 和 <code>TURN_TOKEN</code></li></ul><h3 id="_2-实际测试" tabindex="-1">2. 实际测试 <a class="header-anchor" href="#_2-实际测试" aria-label="Permalink to “2. 实际测试”">​</a></h3><ul><li>找一位朋友，<strong>不开代理</strong>，用手机流量打开 <code>https://send.example.com</code></li><li>验证页面能否正常加载、麦克风权限能否正常请求、通话能否建立</li></ul><hr><h2 id="七、最终效果" tabindex="-1">七、最终效果 <a class="header-anchor" href="#七、最终效果" aria-label="Permalink to “七、最终效果”">​</a></h2><ul><li><strong>访问地址</strong>：<code>https://send.example.com</code></li><li><strong>无需科学上网</strong>：国内用户可直接访问（速度取决于 Cloudflare 节点状况）</li><li><strong>通话方式</strong>：发链接给对方，对方点开即可通话</li><li><strong>隐私性</strong>：端到端加密，数据不经过中心服务器</li></ul><hr><h2 id="八、经验总结" tabindex="-1">八、经验总结 <a class="header-anchor" href="#八、经验总结" aria-label="Permalink to “八、经验总结”">​</a></h2><ol><li><strong>DNS 是核心</strong>：域名解析指向哪里，请求就去哪里。排查问题时，先用 <code>nslookup</code> 和 <code>curl</code> 确认解析和响应头。</li><li><strong>代理软件要配分流</strong>：科学上网工具要正确配置直连规则，否则会干扰正常访问。</li><li><strong>Cloudflare 自定义域是解决国内访问的关键</strong>：<code>workers.dev</code> 被屏蔽，但自定义域走的是 Cloudflare 边缘节点，国内可直接访问。</li><li><strong>耐心排查，逐层剥离</strong>：从 Nginx → DNS → 代理 → 本机缓存，一层层排除，最终定位问题。</li></ol>`,43)])])}const g=e(n,[["render",r]]);export{k as __pageData,g as default};
